"""The drum engines' sample-loop kernels (modules/machines/plaits/src/dsp/lib/drums_sm.s, generated by
gen_drum_kernels.py) on the isolated concrete SHARC+ core: each engine's render (kick_render, snare_render,
hihat_render) built for the DSP (the kernels) against the same engine built with -DPL_DRUMS_C (selcc's C loops, the
code the core digests were recorded from), bit for bit on out[], aux[] and the whole engine state, over random states
(with denormals, +-0, Inf and NaN in some cases), random parameters, triggers and run-on sequences from init; each
kernel leaves every register outside the scratch set as it found it; and drums_sm.s passes the encoding gate with
precedents taken only from stock code inside functions, has no SIMD-mode transfer and stores no DAG register through
its own DAG."""

from __future__ import annotations

import random
import struct
from functools import cache

import pytest

from tools.patchkit import pk_sharc, pk_toolchains

ROOT = pk_toolchains.ROOT
DSP = ROOT / "modules" / "machines" / "plaits" / "src" / "dsp"
LIB = DSP / "lib"
pytestmark = pytest.mark.skipif(
    pk_toolchains.selache_dir() is None,
    reason="selache not built (tools/patchkit/pk_toolchains.py selache)",
)

BASE_SW = 0xB92000
RETURN_SW = 0xBAF100
DATA = 0x200A0000
STACK = 0x200F0000
CALLER_I6 = 0x200F0100
ST, PRM, OUT, AUX = (0x200D0000 + 0x400 * i for i in range(4))
STATE_WORDS = 96
GUARD = 0x5A5A5A5A
SCRATCH = {f"R{i}" for i in (0, 1, 2, 3, 4, 5, 6, 7, 8, 12)} | {
    "I4",
    "I12",
    "LCNTR",
    "CURLCNTR",
    "LADDR",
}
RUNNING = {
    "PC",
    "PCSTK",
    "PCSTKP",
    "EMUCLK",
    "EMUCLK2",
    "TCOUNT",
    "FADDR",
    "DADDR",
    "MODE1STK",
}
HOOK = {
    "M5": 0,
    "M6": 1,
    "M7": 0xFFFFFFFF,
    "M13": 0,
    "M14": 1,
    "M15": 0xFFFFFFFF,
    "MODE1": 0x1011800,
    "MODE2": 1,
    "L6": 0,
    "L7": 0,
}
FLAGS = {"ASTATX", "ASTATY", "STKYX", "STKYY"}
ENGINES = {13: "kick", 14: "snare", 15: "hihat"}


def bits(x: float) -> int:
    return struct.unpack("<I", struct.pack("<f", x))[0]


@cache
def built(engine: str, kernel: bool) -> tuple[pk_sharc.Linked, list[tuple[int, bytes]]]:
    defines = () if kernel else ("PL_DRUMS_C",)
    objs = [
        pk_sharc.compile_c(
            (DSP / "engines" / f"{engine}.c").read_text(),
            include_dirs=[DSP / "engines", LIB, DSP],
            defines=defines,
        ),
        pk_sharc.compile_c(
            (LIB / "svf.c").read_text(), include_dirs=[LIB, DSP], defines=("PL_SVF_C",)
        ),
        pk_sharc.compile_c((LIB / "tables.c").read_text(), include_dirs=[LIB, DSP]),
    ]
    if kernel:
        objs.insert(0, pk_sharc.assemble((LIB / "drums_sm.s").read_text()))
    obj = pk_sharc.merge(objs)
    at, blobs, externs, data_at = DATA, [], {}, {}
    for sec, (blob, align, bss) in obj.data.items():
        at = -(-at // max(align, 8)) * max(align, 8)
        data_at[sec] = at
        blobs.append((at, bytes(len(blob)) if bss else blob))
        at += len(blob)
    for name, (sec, off, _g) in obj.data_symbols.items():
        externs[name] = data_at[sec] + off
    missing = {
        r.symbol
        for r in obj.relocs
        if r.symbol not in obj.symbols and r.symbol not in externs
    }
    assert not missing, missing
    linked = pk_sharc.link(obj, BASE_SW, externs)
    pk_sharc.verify(obj, linked, externs)
    return linked, blobs


class Core:
    def __init__(self, engine: str, kernel: bool) -> None:
        from tools.sharc_dev import sharc_run as sr
        from tools.sharc_dev import sharc_trace as st
        from tools.sharc_dev.sharcldr import LoadedMemory

        self.st = st
        self.linked, blobs = built(engine, kernel)
        payload = self.linked.code_boot
        blocks = [
            {
                "target_address": pk_sharc.SW_ALIAS_BASE + 2 * BASE_SW,
                "byte_count": len(payload),
                "fill": False,
                "payload_offset": 0,
                "payload_len": len(payload),
                "index": 0,
            }
        ]
        for at, blob in blobs:
            blocks.append(
                {
                    "target_address": at,
                    "byte_count": len(blob),
                    "fill": False,
                    "payload_offset": len(payload),
                    "payload_len": len(blob),
                    "index": len(blocks),
                }
            )
            payload += blob
        self.runner = sr.Runner(
            LoadedMemory(payload, blocks),
            BASE_SW,
            breakpoints=[RETURN_SW],
            approx_recips=True,
        )
        self.instructions = 0

    def poke(self, addr: int, word: int) -> None:
        assert self.st._dm_write(
            self.runner.state, addr, 4, self.st.Const(word & 0xFFFFFFFF)
        )

    def peek(self, addr: int) -> int:
        v = self.st._dm_read(self.runner.state, addr, 4)
        assert v is not None
        return int(v.value) & 0xFFFFFFFF

    def put(self, addr: int, words: list[int], guard: int = 2) -> None:
        for k in range(-guard, len(words) + guard):
            self.poke(addr + 4 * k, words[k] if 0 <= k < len(words) else GUARD)

    def get(self, addr: int, n: int, guard: int = 2) -> list[int]:
        return [self.peek(addr + 4 * k) for k in range(-guard, n + guard)]

    def call(
        self, name: str, args: list[int], regs: dict[str, int] | None = None
    ) -> dict[str, int | None]:
        self.poke(STACK, CALLER_I6)
        self.poke(STACK - 4, RETURN_SW - 1)
        r: dict[str | int, int | str] = {
            "I6": STACK,
            "I7": STACK - 8,
            "M5": 0,
            "M6": 1,
            "M7": -1,
            "M13": 0,
            "M14": 1,
            "M15": -1,
        }
        r.update(regs or {})
        for reg, a in zip(("R4", "R8", "R12"), args[:3], strict=False):
            r[reg] = a & 0xFFFFFFFF
        for k, a in enumerate(args[3:]):
            self.poke(STACK + 4 * (k + 1), a)
        run = self.runner.fresh_call(
            self.linked.symbols[name], regs=r, return_address=RETURN_SW
        )
        st = run.state
        self.before = {n: self._val(st, c) for n, c in self.st.UREG_CODES.items()}
        self.depth_before = (len(st.loops), len(st.status_stack), len(st.call_stack))
        res = run.run(5_000_000)
        assert res.halt.reason == "breakpoint" and res.final_pc_sw == RETURN_SW, (
            res.halt.to_json()
        )
        assert not run.state.loops, "loop stack not empty on return"
        self.runner = run
        st = run.state
        self.depth_after = (len(st.loops), len(st.status_stack), len(st.call_stack))
        self.instructions = res.instructions
        return {n: self._val(st, c) for n, c in self.st.UREG_CODES.items()}

    @staticmethod
    def _val(state: object, code: int) -> int | None:
        v = state.uregs.get(code)  # type: ignore[attr-defined]
        x = None if v is None else getattr(v, "value", None)
        return None if x is None else int(x) & 0xFFFFFFFF


SPECIAL = [
    0.0,
    -0.0,
    1e-39,
    -1e-39,
    3e38,
    -3e38,
    float("inf"),
    float("-inf"),
    float("nan"),
]

# per engine: the int words of the state (counters) and their range; everything else is a float
INTS = {
    "kick": {
        0: 300,
        1: 300,
        33: 50,
        34: 70,
    },  # analog pulse counters; synthetic body_env/fm pulse widths
    "snare": {0: 50, 40: 4000},  # analog pulse counter; synthetic hold_counter_
    "hihat": {36 + 8 * i: 1 for i in range(6)},  # the oscillators' high_
}
# float words with the range the engine keeps them in (a phase or frequency outside it indexes outside a table)
RANGES = {
    "kick": {
        14: (0.0, 0.2),
        15: (0.0, 1.0),
        16: (-0.5, 0.5),
        17: (0.0, 1.0),
        18: (0.0, 1.0),
    },
    "snare": {35: (0.0, 1.0), 36: (0.0, 1.0)},
    "hihat": {
        **{32 + 8 * i: (0.0, 1.0) for i in range(6)},
        **{37 + 8 * i: (1e-4, 0.25) for i in range(6)},
        **{38 + 8 * i: (0.1, 0.9) for i in range(6)},
        1: (0.0, 1.0),
        14: (0.0, 1.0),
    },
}
# words that index a table (a NaN or Inf there reads outside it in both builds: unseeded memory on this core)
NOSPECIAL = {"kick": {15, 16}, "snare": set(), "hihat": set()}
UINTS = {
    "kick": {37},
    "snare": {52},
    "hihat": {*range(26, 32), 80},
}  # rng_ words, SquareNoise phases


def rand_state(rng: random.Random, engine: str, special: float) -> list[int]:
    words = []
    for i in range(STATE_WORDS):
        if i in INTS[engine]:
            words.append(rng.choice([0, 0, 1, 2, rng.randrange(INTS[engine][i] + 1)]))
        elif i in UINTS[engine]:
            words.append(rng.getrandbits(32))
        elif i in RANGES[engine]:
            words.append(bits(rng.uniform(*RANGES[engine][i])))
        elif rng.random() < special and i not in NOSPECIAL[engine]:
            words.append(bits(rng.choice(SPECIAL)))
        else:
            words.append(
                bits(rng.uniform(-1.0, 1.0) * rng.choice([1.0, 1.0, 0.1, 0.01, 3.0]))
            )
    return words


def rand_params(rng: random.Random, trigger: int | None = None) -> list[int]:
    def knob() -> float:
        r = rng.random()
        return 0.0 if r < 0.1 else (1.0 if r < 0.2 else rng.random())

    note = rng.choice([rng.uniform(0, 127), 0.0, 127.0, rng.uniform(24, 96)])
    trig = rng.choice([0, 0, 1, 3, 2]) if trigger is None else trigger
    return [bits(note), bits(knob()), bits(knob()), bits(knob()), trig, bits(knob())]


def render(
    core: Core, engine: str, state: list[int], params: list[int], size: int = 16
) -> tuple[list[int], ...]:
    core.put(ST, state)
    core.put(PRM, params)
    core.put(OUT, [GUARD ^ 1] * size)
    core.put(AUX, [GUARD ^ 2] * size)
    core.call(f"{engine}_render.", [ST, PRM, OUT, AUX, size])
    return (
        core.get(OUT, size),
        core.get(AUX, size),
        core.get(ST, STATE_WORDS),
        core.get(PRM, 6),
    )


@pytest.fixture(scope="module", params=[13, 14, 15])
def pair(request: pytest.FixtureRequest) -> tuple[str, Core, Core]:
    engine = ENGINES[request.param]
    return engine, Core(engine, True), Core(engine, False)


def test_render_equals_compiled_c_on_random_states(
    pair: tuple[str, Core, Core],
) -> None:
    engine, ker, ref = pair
    rng = random.Random(100 + len(engine))
    for i in range(30):
        special = 0.0 if i % 3 else 0.05
        st, prm = rand_state(rng, engine, special), rand_params(rng)
        got, want = render(ker, engine, st, prm), render(ref, engine, st, prm)
        assert got == want, (engine, i)


def test_render_runs_on_from_init(pair: tuple[str, Core, Core]) -> None:
    """From init: 60 blocks of 16 with parameter changes and strikes at random spacing, carrying the state."""
    engine, ker, ref = pair
    rng = random.Random(7)
    for core in (ker, ref):
        core.put(ST, [0] * STATE_WORDS)
        core.call(f"{engine}_init.", [ST])
    prm = rand_params(rng, 1)
    for blk in range(60):
        if rng.random() < 0.3:
            prm = rand_params(rng, 1 if rng.random() < 0.5 else 0)
        elif blk:
            prm[4] = 0
        outs = []
        for core in (ker, ref):
            core.put(PRM, prm)
            core.call(f"{engine}_render.", [ST, PRM, OUT, AUX, 16])
            outs.append(
                (core.get(OUT, 16), core.get(AUX, 16), core.get(ST, STATE_WORDS))
            )
        assert outs[0] == outs[1], (engine, blk)


def test_kernel_cost(pair: tuple[str, Core, Core]) -> None:
    engine, ker, ref = pair
    rng = random.Random(3)
    st, prm = rand_state(rng, engine, 0.0), rand_params(rng, 1)
    render(ker, engine, st, prm)
    render(ref, engine, st, prm)
    print(engine, ker.instructions, ref.instructions)
    assert ker.instructions < ref.instructions, (ker.instructions, ref.instructions)


KERNELS = {"kick": ["kick_analog_kernel."]}


@pytest.mark.parametrize("seed", [11, 12])
def test_render_preserves_the_dsp_state(
    pair: tuple[str, Core, Core], seed: int
) -> None:
    """The engine's render (kernels included) from the hook's registers plus random values elsewhere (non-zero L and
    B on every DAG but the C stack's, M6 != 1 on the second seed): every register outside the scratch set, every
    MODE1/MODE2 bit and the stack depths are as before, and the output equals the C's."""
    engine, ker, ref = pair
    rng = random.Random(seed)
    st, prm = rand_state(rng, engine, 0.0), rand_params(rng, 1)
    want = render(ref, engine, st, prm)
    ker.put(ST, st)
    ker.put(PRM, prm)
    ker.put(OUT, [GUARD ^ 1] * 16)
    ker.put(AUX, [GUARD ^ 2] * 16)
    regs: dict[str, int] = dict(HOOK)
    for p in range(16):
        regs[f"R{p}"] = rng.getrandbits(32)
        regs[f"S{p}"] = rng.getrandbits(32)
    for i in (0, 1, 2, 3, 5, 8, 9, 10, 11, 13, 14, 15):
        regs[f"I{i}"] = 0x200C0000 + 4 * rng.randrange(1000)
        regs[f"B{i}"] = 0x200C0000 + 4 * rng.randrange(1000)
        regs[f"L{i}"] = 4 * rng.randrange(1, 64)
    regs["B0"], regs["L0"] = OUT, 8
    regs["B1"], regs["L1"] = ST, 8
    regs["B2"], regs["L2"] = AUX, 8
    for m in (0, 1, 2, 3, 4, 8, 9, 10, 11, 12):
        regs[f"M{m}"] = rng.randrange(-64, 64) & 0xFFFFFFFF
    if seed % 2 == 0:
        regs["M6"] = 3
    for u in ("USTAT1", "USTAT2", "USTAT3", "USTAT4", "PX1", "PX2"):
        regs[u] = rng.getrandbits(32)
    # the C itself relies on L4 = 0 and selcc's modifiers; the kernels must not rely on L0-L2, M6
    regs["L4"] = 0
    after = ker.call(f"{engine}_render.", [ST, PRM, OUT, AUX, 16], regs)
    before = dict(ker.before)
    before["I6"], before["I7"] = CALLER_I6, STACK
    changed = {
        n: (before[n], after[n])
        for n in before
        if n not in SCRATCH | FLAGS | RUNNING and before[n] != after[n]
    }
    assert not changed, changed
    assert ker.depth_after == (
        ker.depth_before[0],
        ker.depth_before[1],
        ker.depth_before[2] - 1,
    )
    got = (ker.get(OUT, 16), ker.get(AUX, 16), ker.get(ST, STATE_WORDS))
    assert got == want[:3]


def test_generated_kernels_are_current() -> None:
    import subprocess
    import sys

    r = subprocess.run(
        [sys.executable, str(LIB / "gen_drum_kernels.py"), "--check"],
        capture_output=True,
        text=True,
    )
    assert r.returncode == 0, r.stdout + r.stderr


def test_kernels_pass_the_strict_encoding_gate() -> None:
    """Every instruction of drums_sm.s has a precedent in stock code that belongs to a function (or in
    encoding_proven.toml), no data transfer runs in SIMD mode and no DAG register is stored through its own DAG."""
    import sqlite3

    from tools.patchkit import pk_encoding_gate as gate

    linked = pk_sharc.link(
        pk_sharc.assemble((LIB / "drums_sm.s").read_text()), BASE_SW, {}
    )

    class Mem:
        def read_sw(self, pc: int, size: int = 6) -> bytes | None:
            lo = 2 * (pc - BASE_SW)
            data = linked.code_boot
            return data[lo : lo + size] if lo + size <= len(data) else None

    db = ROOT / "out" / "sharcdb" / "dt2-1.17.sqlite"
    if not db.exists():
        pytest.skip("no stock instruction database")
    con = sqlite3.connect(f"file:{db}?mode=ro", uri=True)
    rows = con.execute(
        "SELECT DISTINCT form, raw FROM insn WHERE aligned = 1 AND confidence = 'confident' "
        "AND function_sw IS NOT NULL"
    ).fetchall()
    con.close()
    strict = {
        gate.shape_of(f, int(r if isinstance(r, str) else r.hex(), 16)) for f, r in rows
    }
    ranges = [(BASE_SW, BASE_SW + len(linked.code_boot) // 2)]
    bad = gate.check_code(
        Mem(),
        ranges,
        strict | gate.proven_shapes(),
        gate.stock_control_words(db) | gate.proven_words(),
    )
    assert not bad, [gate.format_violation(v) for v in bad]
    assert gate.check_simd_memory(Mem(), ranges) == []
    assert gate.check_same_dag(Mem(), ranges) == []
